/**
 * Desktop-development emulator launcher: `pnpm run firebase:emulators`.
 *
 * Starts the shared Auth+Firestore emulator and makes the human developer's
 * fixed dev identity (`fgcnote-local-dev`, see firebase-dev-data.mjs) durable
 * across restarts:
 *
 *   start    -> emulator boots blank -> seed tracked desktop-evidence/latest.json
 *   running  -> update that file every EXPORT_INTERVAL_MS when content changes
 *   Ctrl+C   -> export the dev UID back to that file -> stop the emulator
 *
 * Everything outside the dev UID (agent sandbox UIDs, rules-check leftovers)
 * intentionally stays blank-per-run. The tracked file is the single source of
 * truth for startup and export. The emulator child runs in its own process
 * group so Ctrl+C reaches this wrapper first and the export always precedes
 * emulator shutdown.
 */
import { spawn } from 'node:child_process'
import { createRequire } from 'node:module'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import {
  exportDevData,
  seedDevData,
  DEV_DATA_FILE
} from '../desktop/scripts/firebase-dev-data.mjs'
import { emulatorEndpointsFromEnv, PROJECT } from '../desktop/scripts/firebase-emulator-lib.mjs'
import {
  createShutdownRequest,
  emulatorSpawnOptions,
  forwardPipedOutput,
  stopEmulatorProcess
} from './emulator-process.mjs'

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const READY_TIMEOUT_MS = 120_000
const EXPORT_INTERVAL_MS = 5 * 60_000
const FIREBASE_CONFIG = process.env.FGCNOTE_FIREBASE_CONFIG
  ? path.resolve(process.env.FGCNOTE_FIREBASE_CONFIG)
  : path.join(REPO_ROOT, 'firebaseLocal', 'firebase.json')

const require = createRequire(import.meta.url)
const firebaseBin = process.env.FGCNOTE_FIREBASE_CLI
  ? path.resolve(process.env.FGCNOTE_FIREBASE_CLI)
  : path.join(
      path.dirname(require.resolve('firebase-tools/package.json')),
      require('firebase-tools/package.json').bin.firebase
    )

const child = spawn(
  process.execPath,
  [
    firebaseBin,
    '--config',
    FIREBASE_CONFIG,
    '--project',
    PROJECT,
    'emulators:start',
    '--only',
    'auth,firestore'
  ],
  emulatorSpawnOptions(REPO_ROOT)
)
forwardPipedOutput(child)

let shuttingDown = false
let exporting = Promise.resolve()
let exportTimer

child.on('exit', (code, signal) => {
  if (exportTimer) clearInterval(exportTimer)
  if (!shuttingDown) {
    // The emulator died on its own (port conflict, crash). Nothing to export
    // from — the endpoints are gone.
    process.exit(code ?? (signal ? 1 : 0))
  }
})

async function endpointReady(url) {
  try {
    const response = await fetch(url)
    return response.ok
  } catch {
    return false
  }
}

async function waitForEmulators() {
  const { authBase, firestoreBase } = emulatorEndpointsFromEnv()
  const firestoreRoot = new URL(firestoreBase).origin
  const deadline = Date.now() + READY_TIMEOUT_MS
  while (Date.now() < deadline) {
    if (child.exitCode !== null) return false
    if ((await endpointReady(authBase)) && (await endpointReady(firestoreRoot))) return true
    await new Promise((resolve) => setTimeout(resolve, 500))
  }
  return false
}

function queueExport(reason) {
  const next = exporting.then(async () => {
    await exportDevData()
    if (reason === 'shutdown') {
      console.log(`\n[dev-data] tracked dataset saved to ${DEV_DATA_FILE}`)
    }
  })
  // A failed periodic backup must not poison the queue forever; shutdown still
  // gets its own attempt. Callers keep `next` so shutdown can fail loudly.
  exporting = next.catch(() => {})
  return next
}

async function shutdown() {
  shuttingDown = true
  if (exportTimer) clearInterval(exportTimer)
  if (child.exitCode !== null) {
    process.exitCode = child.exitCode
    return
  }
  let exitCode = 0
  try {
    await queueExport('shutdown')
  } catch (error) {
    exitCode = 1
    console.error(`[dev-data] shutdown export failed: ${error.message}`)
  }
  try {
    await stopEmulatorProcess(child)
  } catch (error) {
    exitCode = 1
    console.error(`[dev-data] emulator shutdown failed: ${error.message}`)
  }
  process.exitCode = exitCode
}

const requestShutdown = createShutdownRequest(shutdown)
process.on('SIGINT', () => void requestShutdown())
process.on('SIGTERM', () => void requestShutdown())

if (!(await waitForEmulators())) {
  if (child.exitCode === null) {
    console.error('[dev-data] emulators never became ready; stopping.')
    await stopEmulatorProcess(child, { graceful: false })
  }
  process.exit(1)
}

try {
  const seeded = await seedDevData()
  console.log(
    seeded
      ? `[dev-data] restored ${DEV_DATA_FILE}`
      : '[dev-data] no saved dev data yet — starting fresh (it will be saved on exit)'
  )
} catch (error) {
  console.error(`[dev-data] restore failed: ${error.message}`)
  // The persisted developer account is one app-owned dataset. Running after a
  // failed restore would expose a partial account and the periodic exporter
  // could then replace the last good snapshot with that partial state.
  shuttingDown = true
  await stopEmulatorProcess(child)
  process.exit(1)
}

exportTimer = setInterval(() => {
  void queueExport('periodic').catch((error) => {
    console.error(`[dev-data] periodic export failed: ${error.message}`)
  })
}, EXPORT_INTERVAL_MS)

